-- ----------------------------
-- Table structure for alarm
-- ----------------------------
DROP TABLE IF EXISTS `alarm`;
CREATE TABLE `alarm` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `report_time` varchar(255) DEFAULT NULL,
  `report_phone` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `jurisdiction_unit` varchar(255) DEFAULT NULL,
  `content` text,
  `case_end_description` text,
  `alarm_no` varchar(255) DEFAULT NULL,
  `longitude` varchar(127) DEFAULT '' COMMENT '经度',
  `latitude` varchar(127) DEFAULT '' COMMENT '维度',
  `report_phone_location` varchar(255) DEFAULT '' COMMENT '报警电话归属地',
  `report_phone_location_response` text COMMENT '手机号码归属地查询响应',
  `is_identify_person` tinyint(255) unsigned DEFAULT '0' COMMENT '是否识别人员信息',
  `province` varchar(255) DEFAULT NULL,
  `province_code` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `city_code` varchar(255) DEFAULT NULL,
  `county` varchar(255) DEFAULT NULL,
  `county_code` varchar(255) DEFAULT NULL,
  `town` varchar(255) DEFAULT NULL,
  `town_code` varchar(255) DEFAULT NULL,
  `village` varchar(255) DEFAULT NULL,
  `village_code` varchar(255) DEFAULT NULL,
  `poi_name` varchar(255) DEFAULT NULL,
  `poi_address` varchar(255) DEFAULT NULL,
  `poi_xy_lng` varchar(255) DEFAULT NULL,
  `poi_xy_lat` varchar(255) DEFAULT NULL,
  `poi_tag` varchar(255) DEFAULT NULL,
  `address_analyzer_response` text,
  `is_address_analyzer` tinyint(3) unsigned DEFAULT '0' COMMENT '是否地址解析',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2671 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of alarm
-- ----------------------------

