  `phone` varchar(255) NOT NULL DEFAULT '' COMMENT '手机号码',
  `now_address` varchar(255) DEFAULT '' COMMENT '现住地',
  `register_address` varchar(255) NOT NULL DEFAULT '' COMMENT '户籍地',
  `role` varchar(255) DEFAULT '' COMMENT '角色',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3662 DEFAULT CHARSET=utf8mb4;

